// Import the scraped manifest (generated by ribbon_scraper.py)
import ribbonManifest from "../data/ribbon_manifest.json";

// Helper function to get ribbon color by category
function getRibbonColorByCategory(category) {
  const categoryColors = {
    valor: "bg-gradient-to-r from-blue-600 via-white to-red-600",
    service: "bg-gradient-to-r from-green-600 via-yellow-400 to-green-600",
    campaign: "bg-gradient-to-r from-yellow-500 via-green-600 to-red-500",
    unit: "bg-gradient-to-r from-blue-500 via-red-500 to-blue-500",
    reserve: "bg-gradient-to-r from-yellow-400 via-blue-600 to-yellow-400",
    foreign: "bg-gradient-to-r from-red-600 via-white to-green-600",
  };
  return categoryColors[category] || "bg-gray-400";
}

