// ============================================================================
// DD214 PARSING
// ============================================================================

/**
 * Parse DD214 text to extract awards with devices
 * @param {string} rawText - Raw text from DD214 Block 13/18
 * @param {string} branch - Veteran's primary branch of service
 * @returns {Array} Array of { awardId, devices: [], quantity: number }
 */
export function parseDD214Text(rawText, branch = "Army") {
  if (!rawText || typeof rawText !== "string") {
    return [];
  }

  // ============================================================
  // DD214 FORM STRUCTURE:
  // 1. FIELD LABELS = BOLD ALL CAPS
  // 2. INSTRUCTIONS = (parenthetic, often lowercase/mixed case)
  //    These contain EXAMPLE awards like "Silver Star, Bronze Star..."
  // 3. ACTUAL DATA = ALL CAPS, not in parentheses
  //
  // Key: Remove parenthetical content and lowercase text!
  // ============================================================

  let cleanedText = rawText;

  // STEP 1: Remove ALL parenthetical content (instructions/examples)
  cleanedText = cleanedText.replace(/\([^)]*\)/g, " ");

  // STEP 2: Remove instructional patterns
  const INSTRUCTIONAL_PATTERNS = [
    /SILVER\s+STAR.*?BRONZE\s+STAR.*?AIR\s+MEDAL/gi,
    /SUCH\s+AS|FOR\s+EXAMPLE|E\.?G\.?|I\.?E\.?/gi,
    /EXAMPLES?\s+(?:OF\s+)?(?:DECORATIONS|MEDALS|AWARDS)/gi,
    // Remove words with 3+ lowercase letters (instructions, not data)
    /[a-z]{3,}/g,
  ];

  for (const pattern of INSTRUCTIONAL_PATTERNS) {
    cleanedText = cleanedText.replace(pattern, " ");
  }

  // If the cleaned text is nearly empty, the input was likely all instructional
  if (cleanedText.trim().length < 20) {
    return [];
  }

  // Normalize text: uppercase, remove extra spaces
  const normalizedText = cleanedText
    .toUpperCase()
    .replace(/\s+/g, " ")
    .replace(/[,;]/g, " ")
    .trim();

  const foundAwards = [];
  const processedIds = new Set();

  // Check each award against the text
  for (const award of MASTER_AWARDS) {
    // Skip awards not applicable to this branch
    if (!award.branch.includes(branch)) {
      continue;
    }

    let matched = false;
    let matchedAlias = "";

    // Check main name
    if (normalizedText.includes(award.name.toUpperCase())) {
      matched = true;
      matchedAlias = award.name;
    }

    // Check aliases
    if (!matched) {
      for (const alias of award.aliases) {
        if (normalizedText.includes(alias)) {
          matched = true;
          matchedAlias = alias;
          break;
        }
      }
    }

    if (matched && !processedIds.has(award.id)) {
      processedIds.add(award.id);

      // Detect devices
      const devices = detectDevices(normalizedText, matchedAlias, branch);

      // Detect quantity (for oak leaf clusters or stars)
      const quantity = detectQuantity(normalizedText, matchedAlias);

      foundAwards.push({
        awardId: award.id,
        award: award,
        devices: devices,
        quantity: quantity,
        matchedText: matchedAlias,
      });
    }
  }

  return foundAwards;
}

/**
 * Detect devices attached to an award
 */
function detectDevices(text, awardMatch, branch) {
  const devices = [];
  const context = extractContext(text, awardMatch, 50);

  // V Device (Valor)
  if (/W\/?V|WITH\s*V|V\s*DEVICE|VALOR/.test(context)) {
    devices.push({ type: "v_device", position: "center" });
  }

  // C Device (Combat)
  if (/W\/?C|WITH\s*C|C\s*DEVICE|COMBAT\s*DIST/.test(context)) {
    devices.push({ type: "c_device", position: "center" });
  }

  // R Device (Remote)
  if (/W\/?R|WITH\s*R|R\s*DEVICE|REMOTE/.test(context)) {
    devices.push({ type: "r_device", position: "center" });
  }

  // Oak Leaf Clusters (Army/Air Force)
  if (branch === "Army" || branch === "Air Force" || branch === "Space Force") {
    const olcMatch = context.match(/(\d+)\s*(OLC|OAK\s*LEAF)/);
    if (olcMatch) {
      const count = parseInt(olcMatch[1], 10);
      const silverOLC = Math.floor(count / 5);
      const bronzeOLC = count % 5;

      for (let i = 0; i < silverOLC; i++) {
        devices.push({ type: "silver_olc", position: i });
      }
      for (let i = 0; i < bronzeOLC; i++) {
        devices.push({ type: "bronze_olc", position: silverOLC + i });
      }
    } else if (/OLC|OAK\s*LEAF/.test(context)) {
      devices.push({ type: "bronze_olc", position: 0 });
    }
  }

  // Service Stars (Navy/Marines/Coast Guard)
  if (branch === "Navy" || branch === "Marines" || branch === "Coast Guard") {
    const starMatch = context.match(/(\d+)\s*(STAR|STR|\*)/);
    if (starMatch) {
      const count = parseInt(starMatch[1], 10);
      const goldStars = Math.floor(count / 25);
      const silverStars = Math.floor((count % 25) / 5);
      const bronzeStars = count % 5;

      for (let i = 0; i < goldStars; i++) {
        devices.push({ type: "gold_star", position: i });
      }
      for (let i = 0; i < silverStars; i++) {
        devices.push({ type: "silver_star", position: goldStars + i });
      }
      for (let i = 0; i < bronzeStars; i++) {
        devices.push({
          type: "bronze_star",
          position: goldStars + silverStars + i,
        });
      }
    }
  }

  // Arrowhead device
  if (/ARROWHEAD|ARROW/.test(context)) {
    devices.push({ type: "arrowhead", position: 0 });
  }

  return devices;
}

/**
 * Extract text context around a match
 */
function extractContext(text, match, chars) {
  const index = text.indexOf(match);
  if (index === -1) return text;

  const start = Math.max(0, index - chars);
  const end = Math.min(text.length, index + match.length + chars);
  return text.substring(start, end);
}

/**
 * Detect quantity of awards
 */
function detectQuantity(text, awardMatch) {
  const context = extractContext(text, awardMatch, 30);

  // Look for patterns like "(2)", "x2", "2nd", etc.
  const patterns = [/\((\d+)\)/, /x(\d+)/i, /(\d+)(?:ST|ND|RD|TH)\s*AWARD/i];

  for (const pattern of patterns) {
    const match = context.match(pattern);
    if (match) {
      return parseInt(match[1], 10);
    }
  }

  return 1;
}

// ============================================================================
// PRECEDENCE SORTING
// ============================================================================

/**
 * Sort ribbons by branch-specific order of precedence
 * @param {Array} awards - Array of award objects from parseDD214Text
 * @param {string} branch - Branch of service
 * @returns {Array} Sorted awards
 */
export function sortRibbonsByPrecedence(awards, branch) {
  if (!awards || !Array.isArray(awards)) {
    return [];
  }

  return [...awards].sort((a, b) => {
    const precedenceA = a.award?.precedence?.[branch] ?? 999;
    const precedenceB = b.award?.precedence?.[branch] ?? 999;
    return precedenceA - precedenceB;
  });
}

/**
 * Get an award by ID
 */
export function getAwardById(awardId) {
  return MASTER_AWARDS.find((a) => a.id === awardId) || null;
}

/**
 * Get awards applicable to a specific branch
 */
export function getAwardsForBranch(branch) {
  return MASTER_AWARDS.filter((a) => a.branch.includes(branch)).sort(
    (a, b) => (a.precedence[branch] || 999) - (b.precedence[branch] || 999),
  );
}

// ============================================================================
// RACK LAYOUT CALCULATIONS
// ============================================================================

/**
 * Calculate ribbon rack layout
 * @param {Array} sortedAwards - Awards sorted by precedence
 * @param {number} ribbonsPerRow - Ribbons per row (3 or 4)
 * @returns {Array} Array of rows, each containing ribbon objects
 */
export function calculateRackLayout(sortedAwards, ribbonsPerRow = 3) {
  if (!sortedAwards || sortedAwards.length === 0) {
    return [];
  }

  const rows = [];
  const totalRibbons = sortedAwards.length;

  // Calculate how many full rows and remainder
  const fullRows = Math.floor(totalRibbons / ribbonsPerRow);
  const remainder = totalRibbons % ribbonsPerRow;

  let index = 0;

  // Top row (may be partial - should be centered)
  if (remainder > 0) {
    const topRow = {
      ribbons: sortedAwards.slice(index, index + remainder),
      isPartial: true,
      count: remainder,
      alignment: "center",
    };
    rows.push(topRow);
    index += remainder;
  }

  // Full rows
  while (index < totalRibbons) {
    const row = {
      ribbons: sortedAwards.slice(index, index + ribbonsPerRow),
      isPartial: false,
      count: ribbonsPerRow,
      alignment: "full",
    };
    rows.push(row);
    index += ribbonsPerRow;
  }

  return rows;
}

// ============================================================================
// UTILITY EXPORTS
// ============================================================================

export default {
  MASTER_AWARDS,
  DEVICES,
  PRECEDENCE_REGULATIONS,
  parseDD214Text,
  sortRibbonsByPrecedence,
  getAwardById,
  getAwardsForBranch,
  calculateRackLayout,
};
